import{c as d,Q as r,j as e,m as a}from"./chunks/framework.DOi4mjdC.js";const g=JSON.parse('{"title":"Utils API列表","description":"","frontmatter":{},"headers":[{"level":1,"title":"Utils API列表","slug":"utils-api列表"}],"relativePath":"api/Utils-API/Utils-API列表.md","filePath":"api/Utils-API/Utils-API列表.md"}'),i={name:"api/Utils-API/Utils-API列表.md"};function l(n,t,o,s,_,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="utils-api列表" tabindex="-1">Utils API列表 <a class="header-anchor" href="#utils-api列表" aria-label="Permalink to &quot;Utils API列表&quot;">​</a></h1><p><strong>表 1</strong> C++标准库API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>max</td><td>比较相同数据类型的两个数中的最大值。</td></tr><tr><td>min</td><td>比较相同数据类型的两个数中的最小值。</td></tr><tr><td>abs</td><td>获取输入数据的绝对值。</td></tr><tr><td>sqrt</td><td>计算输入数据的平方根。</td></tr><tr><td>integer_sequence</td><td>用于生成一个整数序列。</td></tr><tr><td>tuple</td><td>允许存储多个不同类型元素的容器。</td></tr><tr><td>get</td><td>从tuple容器中提取指定位置的元素。</td></tr><tr><td>make_tuple</td><td>用于便捷地创建tuple对象。</td></tr><tr><td>is_convertible</td><td>在程序编译时判断两个类型之间是否可以进行隐式转换。</td></tr><tr><td>is_base_of</td><td>在程序编译时判断一个类型是否为另一个类型的基类。</td></tr><tr><td>is_same</td><td>在程序编译时判断两个类型是否完全相同。</td></tr><tr><td>is_void</td><td>在程序编译时，检测一个类型是否为void类型。</td></tr><tr><td>is_integral</td><td>在程序编译时，检测一个类型是否为整数类型。</td></tr><tr><td>is_floating_point</td><td>在程序编译时，检测一个类型是否为浮点类型。</td></tr><tr><td>is_array</td><td>在程序编译时，检测一个类型是否为数组类型。</td></tr><tr><td>is_pointer</td><td>在程序编译时，判断一个类型是否为指针类型。</td></tr><tr><td>is_reference</td><td>在程序编译时，检测一个类型是否为引用类型。</td></tr><tr><td>is_const</td><td>在程序编译时，检测一个类型是否为const限定的类型。</td></tr><tr><td>remove_const</td><td>在程序编译时，对传入的模板参数类型移除const限定符。</td></tr><tr><td>remove_volatile</td><td>在程序编译时，对传入的模板参数类型移除volatile限定符。</td></tr><tr><td>remove_cv</td><td>在程序编译时，对传入的模板参数类型移除const限定符或volatile限定符，或同时移除这两种限定符。</td></tr><tr><td>remove_reference</td><td>在程序编译时，从给定类型中移除引用限定符。</td></tr><tr><td>remove_pointer</td><td>在程序编译时，从给定类型中移除指针限定符。</td></tr><tr><td>add_const</td><td>在程序编译时，为指定类型添加const限定符。</td></tr><tr><td>add_volatile</td><td>在程序编译时，为指定类型添加volatile限定符。</td></tr><tr><td>add_cv</td><td>在程序编译时，为指定类型添加const和volatile限定符。</td></tr><tr><td>add_pointer</td><td>在程序编译时，为指定类型添加指针限定符。</td></tr><tr><td>add_lvalue_reference</td><td>在程序编译时，为指定类型添加左值引用限定符。</td></tr><tr><td>add_rvalue_reference</td><td>在程序编译时，为指定类型添加右值引用限定符。</td></tr><tr><td>enable_if</td><td>在程序编译时根据某个条件启用或禁用特定的函数模板、类模板或模板特化。</td></tr><tr><td>conditional</td><td>在程序编译时根据一个布尔条件从两个类型中选择一个类型。</td></tr><tr><td>integral_constant</td><td>用于封装一个编译时常量整数值，是标准库中许多类型特性和编译时计算的基础组件。</td></tr></tbody></table><p><strong>表 2</strong> 平台信息获取API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>PlatformAscendC</td><td>在实现Host侧的Tiling函数时，可能需要获取一些硬件平台的信息，来支撑Tiling的计算，比如获取硬件平台的核数等信息。PlatformAscendC类提供获取这些平台信息的功能。</td></tr><tr><td>PlatformAscendCManager</td><td>基于Kernel Launch算子工程，通过基础调用（Kernel Launch）方式调用算子的场景下，可能需要获取硬件平台相关信息，比如获取硬件平台的核数。PlatformAscendCManager类提供获取平台信息的功能。</td></tr></tbody></table><p><strong>表 3</strong> Tiling调测API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>OpTilingRegistry</td><td>OpTilingRegistry类属于context_ascendc命名空间，主要用于加载Tiling实现的动态库，并获取算子的Tiling函数指针以进行调试和验证。</td></tr><tr><td>ContextBuilder</td><td>ContextBuilder类提供一系列的API接口，支持手动构造类来验证Tiling函数以及KernelContext类用于TilingParse函数的验证。</td></tr></tbody></table><p><strong>表 4</strong> Tiling模板编程API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>模板参数定义</td><td>通过该类接口进行模板参数ASCENDC_TPL_ARGS_DECL和模板参数组合ASCENDC_TPL_ARGS_SEL（即可使用的模板）的定义。</td></tr><tr><td>GET_TPL_TILING_KEY</td><td>Tiling模板编程时，开发者通过调用此接口自动生成TilingKey。该接口将传入的模板参数通过定义的位宽，转成二进制，按照顺序组合后转成uint64数值，即TilingKey。</td></tr><tr><td>ASCENDC_TPL_SEL_PARAM</td><td>Tiling模板编程时，开发者通过调用此接口自动生成并配置TilingKey。</td></tr></tbody></table><p><strong>表 5</strong> RTC API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>aclrtcCompileProg</td><td>编译接口，编译指定的程序。</td></tr><tr><td>aclrtcCreateProg</td><td>通过给定的参数，创建编译程序的实例。</td></tr><tr><td>aclrtcDestroyProg</td><td>销毁编译程序的实例。</td></tr><tr><td>aclrtcGetBinData</td><td>获取编译后的二进制数据。</td></tr><tr><td>aclrtcGetBinDataSize</td><td>获取编译的二进制数据大小。用于在aclrtcGetBinData获取二进制数据时分配对应大小的内存空间。</td></tr><tr><td>aclrtcGetCompileLogSize</td><td>获取编译日志的大小。用于在aclrtcGetCompileLog获取日志内容时分配对应大小的内存空间。</td></tr><tr><td>aclrtcGetCompileLog</td><td>获取编译日志的内容，以字符串形式保存。</td></tr></tbody></table><p><strong>表 6</strong> log API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>ASC_CPU_LOG</td><td>提供Host侧打印Log的功能。开发者可以在算子的TilingFunc代码中使用ASC_CPU_LOG_XXX接口来输出相关内容。</td></tr></tbody></table><p><strong>表 7</strong> 调测接口列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>printf</td><td>在算子Kernel侧的实现代码中，需要输出日志信息时，调用printf接口打印相关内容。</td></tr><tr><td>assert</td><td>本接口在SIMT VF调试场景下提供assert断言功能。在算子Kernel侧的SIMT VF实现代码中，如果assert的内部条件判断不为真，则会输出assert条件，并将输入的信息格式化打印在屏幕上。</td></tr><tr><td>__trap</td><td>在SIMT VF实现代码中调用此接口会中断算子的运行。</td></tr><tr><td>clock</td><td>本接口在SIMT VF调试场景中提供Clock时间戳功能，用于记录从程序启动到接口调用时刻所经历的时钟周期数（Cycle Count），便于精确分析执行延迟和性能瓶颈。</td></tr></tbody></table>',15)])])}const p=d(i,[["render",l]]);export{g as __pageData,p as default};
